// Shared header & footer — single source of truth for nav across every page (no duplicate markup).
const NAV_LINKS = [
  { href: "index.html", label: "Home", key: "home" },
  { href: "about.html", label: "About", key: "about" },
  { href: "journey.html", label: "Journey", key: "journey" },
  { href: "events.html", label: "Events", key: "events" },
  { href: "gallery.html", label: "Gallery", key: "gallery" },
  { href: "achievements.html", label: "Achievements", key: "achievements" },
  { href: "team.html", label: "Team", key: "team" },
  { href: "assistant.html", label: "Prakriti AI", key: "assistant" },
];

const LOGO_DATA_URI = "data:image/png;base64,";

function renderLogoMark(size) {
  return `<img src="${LOGO_DATA_URI}" alt="Panchtatva emblem" width="${size}" height="${size}" style="width:${size}px;height:${size}px;border-radius:50%;object-fit:cover;" loading="eager">`;
}

function renderHeader(activeKey) {
  const links = NAV_LINKS.map(l =>
    `<a href="${l.href}" ${l.key === activeKey ? 'aria-current="page"' : ''}>${l.label}</a>`
  ).join("");
  const mobileLinks = NAV_LINKS.map(l =>
    `<a href="${l.href}" ${l.key === activeKey ? 'aria-current="page"' : ''}>${l.label}</a>`
  ).join("");

  return `
  <div class="container nav-row">
    <a href="index.html" class="brand">
      ${renderLogoMark(40)}
      <span>Panchtatva</span>
    </a>
    <nav class="nav-links" aria-label="Primary">${links}</nav>
    <div style="display:flex;align-items:center;gap:10px;">
      <a href="join.html" class="btn btn-primary btn-sm nav-cta">Join Us</a>
      <button class="hamburger" id="hamburgerBtn" aria-label="Open menu" aria-expanded="false" aria-controls="mobileMenu">
        <span></span><span></span><span></span>
      </button>
    </div>
  </div>
  <div class="mobile-menu" id="mobileMenu" role="dialog" aria-modal="true" aria-label="Site menu">
    <div class="mobile-menu-top">
      <span class="brand" style="color:var(--cream-100)">${renderLogoMark(36)} Panchtatva</span>
      <button class="close-btn" id="closeMenuBtn" aria-label="Close menu">${icon('x')}</button>
    </div>
    <nav aria-label="Mobile">${mobileLinks}</nav>
    <a href="join.html" class="btn btn-primary" style="margin-top:24px;">Join Us</a>
  </div>`;
}

function renderFooter() {
  return `
  <div class="container">
    <div class="footer-grid">
      <div>
        <div class="footer-brand">
          ${renderLogoMark(46)}
          <div>
            <div style="font-family:var(--font-display);font-size:1.1rem;color:var(--cream-100)">Panchtatva</div>
            <div style="font-size:0.8rem;">Environmental Studies Society</div>
          </div>
        </div>
        <p style="max-width:340px;font-size:0.9rem;">Zakir Husain Delhi College (Evening), University of Delhi. Preserving Nature. Inspiring Action. Building Tomorrow.</p>
      </div>
      <div class="footer-col">
        <h4>Explore</h4>
        <a href="journey.html">Journey</a>
        <a href="events.html">Events</a>
        <a href="gallery.html">Gallery</a>
        <a href="achievements.html">Achievements</a>
      </div>
      <div class="footer-col">
        <h4>Connect</h4>
        <a href="team.html">Meet the Team</a>
        <a href="assistant.html">Ask Prakriti AI</a>
        <a href="join.html">Recruitment</a>
        <a href="#" id="footerInstagram" target="_blank" rel="noopener">Instagram ↗</a>
      </div>
    </div>
    <div class="footer-bottom">
      <span>© <span id="year"></span> Panchtatva Eco-Club · Zakir Husain Delhi College (Evening), University of Delhi</span>
      <span>Panchtatva OS v1.0 — Freshers Launch</span>
    </div>
  </div>`;
}

function loadInstagramEmbedScript() {
  if (document.getElementById("ig-embed-script")) return;
  const s = document.createElement("script");
  s.id = "ig-embed-script";
  s.async = true;
  s.src = "https://www.instagram.com/embed.js";
  document.body.appendChild(s);
}

function processInstagramEmbeds() {
  loadInstagramEmbedScript();
  // embed.js exposes window.instgrm once loaded; if it's already loaded, ask it to
  // scan the page again for any blockquotes we just inserted via innerHTML.
  if (window.instgrm && window.instgrm.Embeds) {
    window.instgrm.Embeds.process();
  } else {
    // script not ready yet on first load — it self-processes once it finishes loading,
    // but poll briefly in case content was inserted before that finishes.
    let tries = 0;
    const t = setInterval(() => {
      tries++;
      if (window.instgrm && window.instgrm.Embeds) {
        window.instgrm.Embeds.process();
        clearInterval(t);
      } else if (tries > 20) {
        clearInterval(t);
      }
    }, 250);
  }
}

function instagramEmbedHTML(url) {
  return `
  <blockquote class="instagram-media" data-instgrm-permalink="${url}" data-instgrm-version="14"
    style="background:#FFF; border:0; border-radius:12px; box-shadow:var(--shadow-sm); margin: 0 auto 16px; max-width:540px; width:100%;">
  </blockquote>`;
}

function mountLayout(activeKey) {
  const headerEl = document.getElementById("site-header");
  const footerEl = document.getElementById("site-footer");
  if (headerEl) headerEl.innerHTML = renderHeader(activeKey);
  if (footerEl) footerEl.innerHTML = renderFooter();

  const yearEl = document.getElementById("year");
  if (yearEl) yearEl.textContent = new Date().getFullYear();

  // Mobile menu toggle
  const hamburger = document.getElementById("hamburgerBtn");
  const closeBtn = document.getElementById("closeMenuBtn");
  const menu = document.getElementById("mobileMenu");
  if (hamburger && menu) {
    hamburger.addEventListener("click", () => {
      menu.classList.add("open");
      hamburger.setAttribute("aria-expanded", "true");
      document.body.style.overflow = "hidden";
    });
  }
  if (closeBtn && menu) {
    closeBtn.addEventListener("click", () => {
      menu.classList.remove("open");
      hamburger?.setAttribute("aria-expanded", "false");
      document.body.style.overflow = "";
    });
  }
  menu?.querySelectorAll("a").forEach(a => a.addEventListener("click", () => {
    menu.classList.remove("open");
    document.body.style.overflow = "";
  }));

  // Header shadow on scroll
  const header = document.querySelector(".site-header");
  window.addEventListener("scroll", () => {
    if (header) header.classList.toggle("scrolled", window.scrollY > 8);
  }, { passive: true });
}
